function debounce(fn, ms) {
  let timer;
  return (x) => {
    if (timer === undefined) fn(x);
    clearTimeout(timer);
    timer = setTimeout(() => (timer = undefined), ms);
  };
}

const tap = debounce((n) => console.log("tap " + n), 40);

tap(1);
setTimeout(() => tap(2), 20);
setTimeout(() => tap(3), 40);
setTimeout(() => tap(4), 100);
